import{_ as r,l as P,o as e,c as o,v as t,p as c,x as s,d as h,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"PSPACE 与 Savitch","description":"","frontmatter":{"title":"PSPACE 与 Savitch","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pspace-savitch.md","filePath":"cs/pspace-savitch.md","lastUpdated":1789023840000}'),n={name:"cs/pspace-savitch.md"};function S(E,a,d,m,A,C){const i=P("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="pspace-与-savitch" tabindex="-1">PSPACE 与 Savitch <a class="header-anchor" href="#pspace-与-savitch" aria-label="Permalink to &quot;PSPACE 与 Savitch&quot;">​</a></h1><div class="epigraph"><p>多项式空间可判定的语言构成 PSPACE；Savitch 用可达性的分治把非确定空间平方变成确定空间。</p><footer>—— 据 Savitch, Relationships Between Nondeterministic and Deterministic Tape Complexities, 1970；Sipser 整理</footer></div><p>上一课<a href="/cs/time-hierarchy">时间层级</a>给时间分级。缺口是<strong>空间</strong>：工作带格数。PSPACE \\(= \\bigcup_k \\mathrm{DSPACE}(n^k)\\)。NPSPACE 看起来更大，Savitch 定理：\\(\\mathrm{NSPACE}(s)\\subseteq\\mathrm{DSPACE}(s^2)\\)（\\(s\\ge\\log n\\)），于是 \\(\\mathrm{PSPACE}=\\mathrm{NPSPACE}\\)。主干 P/NP 没有这样的塌缩。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>配置图：顶点是 TM 配置（多项式空间时配置指数多）。非确定空间 \\(s\\) 的接受 = 从起始配置沿边走到接受配置，路径长至多指数。Savitch：谓词 \\(\\mathrm{CanYield}(c_1,c_2,t)\\)「\\(t\\) 步内从 \\(c_1\\) 到 \\(c_2\\)」对半枚举中间配置，递归深度 \\(O(\\log t)=O(s)\\)，每层存一个配置 \\(O(s)\\)，总空间 \\(O(s^2)\\)。时间仍指数——空间算法可以很慢。</p><p>TQBF（带量词的布尔公式）PSPACE 完全，点名；证明形状像交替 \\(\\exists\\forall\\)，本课不写完归约。</p><h3 id="空间可复用-时间不能" tabindex="-1">空间可复用，时间不能 <a class="header-anchor" href="#空间可复用-时间不能" aria-label="Permalink to &quot;空间可复用，时间不能&quot;">​</a></h3><p>写过的格子能擦。故空间 \\(s\\) 的时间上界 \\(2^{O(s)}\\)（配置数）。\\(P\\subseteq\\mathrm{NP}\\subseteq\\mathrm{PSPACE}\\subseteq\\mathrm{EXP}\\)，中间是否相等开放。Savitch 的平方对对数空间很痛：NL 是否等于 L 仍开，下一课。</p><p><span class="marginnote">Savitch 1970。Sipser 用可达性讲。Stockmeyer–Meyer 的 TQBF 完全性是 PSPACE 的 Cook 定理。本课要塌缩与配置图，不完全性证明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画配置图，写 \\(\\mathrm{CanYield}\\) 的递归。强调确定性模拟不枚举成功路之外的猜测内容——猜测写在配置里，递归只问可达。对照<a href="/cs/np-reduction">多项式归约</a>：这里比较的是空间类等式，不是 NPC。</p>',11)),(e(),c(p,null,{default:s(()=>[l(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NCFG%5B%22NSPACE(s)%20%E9%85%8D%E7%BD%AE%E5%9B%BE%22%5D%20--%3E%20REACH%5B%22%E4%B8%AD%E7%82%B9%E5%88%86%E6%B2%BB%E5%8F%AF%E8%BE%BE%22%5D%0A%20%20REACH%20--%3E%20DET%5B%22DSPACE(s%C2%B2)%22%5D%0A%20%20DET%20--%3E%20EQ%5B%22PSPACE%20%3D%20NPSPACE%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>PSPACE 完全问题（游戏、带量词布尔）直觉是「多项式深的博弈」。时间层级说明 EXP 更大；PSPACE 与 EXP 是否相等开放。不要把「指数配置」写成 PSPACE 不在 P 的证明——那只是上界。</p><p>线性空间、多项式空间的差别也层级化（空间层级几乎无对数因子），本课点名。</p><p>配置图的边可在多项式空间判定（模拟一步）。Savitch 并不把时间变成多项式：递归树仍指数。TQBF 完全性让「多项式深博弈」成为 PSPACE 的脸谱，对照 SAT 的「存在短证书」。\\(NP\\subseteq PSPACE\\) 因为证书可在多项式空间里逐位猜并擦掉。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 TQBF 完全，不引入 IP（后课）。不把 Savitch 的平方改进到线性（未知）。后课默认：PSPACE \\(=\\) NPSPACE；空间平方换确定。下一课对数空间 L 与 NL。</p><p>空间可擦、时间不能：这是 \\(PSPACE\\) 能装下整份 NP 证书又装得下多项式深博弈的原因。平方代价在对数空间不可接受，故 \\(L\\) 与 \\(NL\\) 下一课单独开。</p><p>上一课留下的缺口在本课收口；「PSPACE 与 Savitch」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PSPACE 是多项式工作空间；时间可指数。</li><li>Savitch：非确定空间平方即可确定化。</li><li>\\(P\\subseteq NP\\subseteq PSPACE\\subseteq EXP\\)，中间开放。</li><li>出处：Savitch, 1970；Sipser。</li></ul>',10))])}const v=r(n,[["render",S]]);export{u as __pageData,v as default};
